Sys.unsetenv("LC_ALL")
source("R/load.R");load_vetblcm()
d<-read_blcm_data("examples/example_sample_level.xlsx")
p<-utils::read.csv("examples/simulated_priors.csv",stringsAsFactors=FALSE,check.names=FALSE)
metadata<-list(project_name="SIMULATED EXAMPLE ONLY",pathogen="Simulated analyte",t1="Simulated T1",t2="Simulated T2",specimen="Simulated specimen",target_population="Simulated target population",source_population="Simulation",unit="sample",purpose="research",case_definition="Known generating latent binary status",comparator_reference="Simulated external-information scenario",grouping_independent=TRUE,procedures_comparable="yes",independent_sampling=TRUE,priors_independent=TRUE,label_confirmed=TRUE,label_rationale="Explicit Se1 and Sp1 lower bound 0.5 in this simulation; not a general assay assumption",expert_override=FALSE,override_rationale="")
pop<-data.frame(Population=c("Low","Medium","High"),Definition=c("Simulated lower prevalence","Simulated middle prevalence","Simulated higher prevalence"),Rationale="SIMULATED EXAMPLE ONLY",Prior_source="Simulation",stringsAsFactors=FALSE)
settings<-mcmc_settings("final",adapt=3000,burnin=8000,iterations=24000)
cat("Fitting independent model\n");ind<-run_blcm(d,p,"sample","independent",settings,metadata,pop)
cat("Fitting positive model\n");dep<-run_blcm(d,p,"sample","positive",settings,metadata,pop)
alt<-dep$priors$table;alt$Prior_type<-"alpha_beta";alt$Alpha[3:4]<-alt$Alpha[3:4]/2;alt$Beta[3:4]<-alt$Beta[3:4]/2;alt$Rationale[3:4]<-"SIMULATED alternative: halve external comparator concentration; no universal prior strength recommendation"
scenarios<-list(Weak=weak_prior_scenario(dep),Alternative=alt)
cat("Running sensitivity\n");sens<-run_prior_sensitivity(dep,scenarios,progress=cat)
cat("Exporting report and reproducibility bundle\n")
comparison<-list(independent=ind,positive=dep)
export_analysis(dep,"reports/example_analysis",comparison,sens,review=list(),language="zh")
saveRDS(list(fit=dep,comparison=comparison,sensitivity=sens),"validation/example_full.rds")
stopifnot(file.exists("reports/example_analysis/report.html"),length(openxlsx::getSheetNames("reports/example_analysis/VetBLCM_results.xlsx"))>=15)
cat("EXAMPLE END-TO-END COMPLETED. Report remains exploratory until actual scientific review.\n")
